begin
 source:=public.get_assignment_repolight_source_v1(actor,assignment,learner);
 run:=public.begin_assignment_repolight_run_v1(actor,assignment,learner,completed_run,'{"connectionRef":"archive_fixture","workspaceRef":"archive_workspace","installationRef":"archive_installation"}',request,source->'source');
 held:=public.advance_assignment_repolight_run_v1(actor,assignment,learner,completed_run,'claim','{}'); token:=(held->>'lease_token')::uuid;generation:=(held->>'lease_generation')::integer;
 perform public.advance_assignment_repolight_run_v1(actor,assignment,learner,completed_run,'record_remote',jsonb_build_object('leaseToken',token,'leaseGeneration',generation,'analysisId',analysis_id));
 saved_report:=jsonb_build_object('schemaVersion','1.0','analysisId',analysis_id,'reportRef',analysis_id,'requestFingerprint',run->>'request_fingerprint','clientBinding',run#>'{create_envelope,clientBinding}','reportDigest',expected_digest,'bundle',bundle);
 perform public.advance_assignment_repolight_run_v1(actor,assignment,learner,completed_run,'complete',jsonb_build_object('leaseToken',token,'leaseGeneration',generation,'result',saved_report));
 select to_jsonb(d) into doc_before from public.assignment_docs d where d.id='f2940000-0000-4000-8000-000000000030';
 perform public.import_assignment_repolight_feedback_v1(actor,assignment,learner,completed_run,import_id,'repository',(doc_before->>'updated_at')::timestamptz,expected_digest,null);
 select to_jsonb(i) into saved_import from public.assignment_repolight_feedback_imports i where id=import_id;
 source:=public.get_assignment_repolight_source_v1(actor,assignment,learner);
 queued:=public.begin_assignment_repolight_run_v1(actor,assignment,learner,queued_run,'{"connectionRef":"archive_fixture","workspaceRef":"archive_workspace","installationRef":"archive_installation"}',request,source->'source');
 -- Erase every persisted subject, including the queued unknown-create outcome.
 foreach binding_id in array array[(run->>'subject_binding_id')::uuid,(queued->>'subject_binding_id')::uuid] loop
  erasure_id:=gen_random_uuid();binding_row:=public.begin_repolight_subject_erasure_v1(actor,binding_id,erasure_id);
  receipt:=jsonb_build_object('schemaVersion','1.0','operationRef',erasure_id,'installationRef',binding_row->>'installation_ref','subjectRef',binding_row->>'subject_ref','status','erased','absenceVerified',true);
  perform public.record_repolight_subject_erasure_v1(actor,binding_id,erasure_id,receipt);
 end loop;
 if (select count(*) from public.assignment_repolight_runs where assignment_id=assignment)<>2 or (select result_json from public.assignment_repolight_reports where run_id=completed_run) is distinct from saved_report then raise exception 'Provider proof changed portable local facts';end if;
