 result:=public.begin_classroom_archive_export_v2(export_id,actor,course,repeat('1',64),'293_repolight_report_service','abcdef1234567890','{"mode":"teacher_managed","delete_after":null}',2,2);
 if not coalesce((result->>'ok')::boolean,false) then raise exception 'Current-v2 export failed: %',result;end if;
 archive_id:=(result->>'archive_id')::uuid;counts:=result->'resource_counts';
 if counts->>'assignment_repolight_runs'<>'2' or counts->>'assignment_repolight_reports'<>'1' or counts->>'assignment_repolight_feedback_imports'<>'1' then raise exception 'New report resources missing from actual export registry';end if;
 -- Read exactly the current registry's classroom rows, then apply the current
 -- TS detachRepoLightArchiveResources projection solely to operational columns.
 for resource in select table_name,primary_key_columns[1] pk from public.classroom_archive_resource_contract_versions where format_version=2 order by export_position loop
  execute format('insert into pg_temp.repolight_archive_expected select %L,source.%I,to_jsonb(source) from public.%I source where public.resolve_classroom_archive_resource_classroom_id_versioned(2,%L,source.%I)=$1',resource.table_name,resource.pk,resource.table_name,resource.table_name,resource.pk) using course;
 end loop;
 update pg_temp.repolight_archive_expected set row_data=row_data||jsonb_build_object('subject_binding_id',null,'detached',true,'status',case when row_data->>'status' in('completed','failed','stale') then row_data->>'status' else 'stale' end,'lease_token',null,'lease_expires_at',null,'next_retry_at',null) where table_name='assignment_repolight_runs';
 archive_path:=format('%s/%s/%s/classroom-v2.tar.gz',actor,course,archive_id);
 if not public.stage_classroom_archive_object_upload_v2(export_id,actor,'classroom-archives',archive_path,repeat('2',64),1024,2) then raise exception 'Export upload intent rejected';end if;
 result:=public.complete_classroom_archive_export_v2(export_id,actor,'classroom-archives',archive_path,repeat('2',64),repeat('3',64),1024,65536,counts,2,counts,'{"total_count":0,"total_bytes":0,"by_bucket":{}}','{"read_back_verified":true,"artifact_checksum_verified":true,"manifest_verified":true,"resource_checksums_verified":true,"resource_counts_verified":true,"storage_objects_verified":true,"actor_snapshots_verified":true}');
 if not coalesce((result->>'ok')::boolean,false) then raise exception 'Current-v2 completion failed: %',result;end if;
 result:=public.begin_classroom_archive_compaction_v2(compact_id,actor,course,archive_id,repeat('4',64),2);
 if not coalesce((result->>'ok')::boolean,false) then raise exception 'Cold compaction begin failed: %',result;end if;
 for resource in select table_name from public.classroom_archive_resource_contract_versions where format_version=2 order by export_position loop
  select jsonb_agg(row_data order by row_id) into rows_value from pg_temp.repolight_archive_expected where table_name=resource.table_name;
  if rows_value is not null then perform public.stage_classroom_archive_restore_rows(compact_id,actor,resource.table_name,rows_value);end if;
 end loop;
 perform public.stage_classroom_archive_compaction_objects(compact_id,actor,'[]');
 actors:=jsonb_build_array(jsonb_build_object('actor_id',actor,'role','teacher'),jsonb_build_object('actor_id',learner,'role','student'));
 verification:=jsonb_build_object('operation_id',compact_id,'archive_id',archive_id,'artifact_sha256',repeat('2',64),'content_sha256',repeat('3',64),'verified_at',clock_timestamp(),'read_back_verified',true,'artifact_checksum_verified',true,'manifest_verified',true,'resource_checksums_verified',true,'resource_counts_verified',true,'storage_objects_verified',true,'actor_snapshots_verified',true,'schema_adapter_verified',true,'actor_references_resolved',true,'source_object_cleanup_staged',true);
 result:=public.complete_classroom_archive_compaction_v2(compact_id,actor,actors,verification,2);
 if not coalesce((result->>'ok')::boolean,false) or exists(select 1 from public.classrooms where id=course) or exists(select 1 from public.assignment_repolight_runs where classroom_id=course) or not exists(select 1 from public.classroom_cold_tombstones t where t.classroom_id=course and t.archive_id=(result->>'archive_id')::uuid) then raise exception 'Cold row removal failed: %',result;end if;
 result:=public.begin_classroom_archive_restore_v2(restore_id,actor,course,archive_id,repeat('5',64),'134_blueprint_test_question_ordinal_identity',chain,counts,'[]',2147483648,2,2,counts);
 if not coalesce((result->>'ok')::boolean,false) then raise exception 'Current restore begin failed: %',result;end if;
 for resource in select table_name from public.classroom_archive_resource_contract_versions where format_version=2 order by export_position loop
  select jsonb_agg(row_data order by row_id) into rows_value from pg_temp.repolight_archive_expected where table_name=resource.table_name;
  if rows_value is not null then
   result:=public.stage_classroom_archive_restore_rows_v2(restore_id,actor,resource.table_name,rows_value,2);
   if not coalesce((result->>'ok')::boolean,false) then raise exception 'Restore staging rejected %: %',resource.table_name,result;end if;
  end if;
 end loop;
 result:=public.complete_classroom_archive_restore_v2(restore_id,actor,jsonb_build_object('archive_checksum_verified',true,'manifest_verified',true,'resource_checksums_verified',true,'resource_counts_verified',true,'storage_objects_verified',true,'actor_snapshots_verified',true,'schema_adapter_available',true,'restored_storage_objects_verified',true,'adapter_chain',chain),2);
 if not coalesce((result->>'ok')::boolean,false) then raise exception 'Current restore completion failed: %',result;end if;
 if (select result_json from public.assignment_repolight_reports where run_id=completed_run) is distinct from saved_report or (select to_jsonb(i) from public.assignment_repolight_feedback_imports i where id=import_id) is distinct from saved_import then raise exception 'Restore altered immutable report/import receipt';end if;
 if exists(select 1 from public.assignment_repolight_runs where classroom_id=course and (not detached or subject_binding_id is not null or lease_token is not null or lease_expires_at is not null or next_retry_at is not null)) or (select status from public.assignment_repolight_runs where id=queued_run)<>'stale' or (select status from public.assignment_repolight_runs where id=completed_run)<>'completed' then raise exception 'Restored operational authority not detached';end if;
 result:=public.read_assignment_repolight_run_v1(actor,assignment,learner,completed_run,true);
 if result->'report' is distinct from saved_report or coalesce((result->>'source_current')::boolean,true) then raise exception 'Detached cached read lost report or regained source authority';end if;
 -- Unarchive solely to prove the detached guard, independent of archive denial.
 update public.classrooms set archived_at=null where id=course;
 begin perform public.advance_assignment_repolight_run_v1(actor,assignment,learner,queued_run,'claim','{}');raise exception 'Restored old job resumed';exception when sqlstate '55000' then if sqlerrm<>'repolight_detached_report' then raise;end if;end;
 begin perform public.import_assignment_repolight_feedback_v1(actor,assignment,learner,completed_run,import_id,'repository',clock_timestamp(),expected_digest,null);raise exception 'Restored report imported old subject feedback';exception when sqlstate '55000' then if sqlerrm<>'repolight_detached_report' then raise;end if;end;
end $roundtrip$;
reset role;
rollback;
